<template>
 <svg v-if="!markerOnly||pointer!==null||cursor>=start&&cursor<=start+span" class="music-ruler" :class="{'marker-only':markerOnly}" :style="markerOnly?{left:offset+'px'}:null" :width="width" :height="markerOnly?'100%':28" role="slider" tabindex="0" :aria-label="$t('Cursor de edición')" :aria-valuemin="start" :aria-valuemax="start+span" :aria-valuenow="cursor" @pointerdown.stop="begin" @pointermove.stop="move" @pointerup.stop="finish" @pointercancel.stop="cancel" @lostpointercapture="cancel" @keydown.left.stop.prevent="$emit('seek',Math.max(0,cursor-48))" @keydown.right.stop.prevent="$emit('seek',cursor+48)">
  <template v-if="!markerOnly"><g v-for="tick in ticks" :key="tick"><line :x1="x(tick)" :y1="tick%192===0?11:20" :x2="x(tick)" y2="28" stroke="#66788e"/><text v-if="tick%192===0" :x="x(tick)+5" y="15" fill="#bed0e6" font-size="10">{{tick/192+1}}</text></g><path v-if="cursor>=start&&cursor<=start+span" :d="`M ${x(cursor)-5} 0 h 10 l -5 7 z`" fill="#f2c065" /></template>
  <template v-else><line :x1="x(cursor)" y1="0" :x2="x(cursor)" y2="100%" stroke="#f2c065" pointer-events="none"/><line class="cursor-hit" :x1="x(cursor)" y1="0" :x2="x(cursor)" y2="100%" stroke="transparent" stroke-width="14" pointer-events="stroke"/></template>
 </svg>
</template>
<script>
import {timelineRatio,timelineTime} from '../editor/timeline.mjs';
export default {props:{start:Number,span:Number,width:Number,cursor:Number,markerOnly:Boolean,offset:{type:Number,default:0}},emits:['seek','scrub-start','scrub-end'],data(){return {pointer:null};},computed:{ticks(){const step=this.span/this.width>2?Math.max(192,Math.ceil(this.span/Math.max(1,this.width)*64/192)*192):48;return Array.from({length:Math.ceil(this.span/step)+1},(_,i)=>Math.ceil(this.start/step)*step+i*step);}},methods:{x(tick){return timelineRatio(tick,this.start,this.span)*this.width;},seek(e){const b=e.currentTarget.getBoundingClientRect();if(b.width>0)this.$emit('seek',timelineTime((e.clientX-b.left)/b.width,this.start,this.span));},begin(e){if(e.button!==0||this.pointer!==null)return;e.preventDefault();this.pointer=e.pointerId;e.currentTarget.setPointerCapture(e.pointerId);this.$emit('scrub-start');this.seek(e);},move(e){if(this.pointer===e.pointerId)this.seek(e);},finish(e){if(this.pointer!==e.pointerId)return;this.seek(e);this.cancel();},cancel(){if(this.pointer===null)return;this.pointer=null;this.$emit('scrub-end');}}};
</script>
<style scoped>.music-ruler{display:block;background:#1d2836;cursor:crosshair;user-select:none;touch-action:none;border-bottom:1px solid #3b495b}.music-ruler.marker-only{position:absolute;top:0;background:none;border:0;pointer-events:none;z-index:4;overflow:hidden}.marker-only .cursor-hit{cursor:ew-resize}.music-ruler:focus-visible{outline:2px solid #77c7ff;outline-offset:-2px}</style>
